#!/usr/bin/env node
// Generates the files of meta/ that are derived from the rest of the repository, so they cannot drift:
//   meta/guided/skills/*/references/*      the book catalog, the 91 pair verdicts, schemas and guides the guided skills read
//   meta/bundles/guided-<preset>/          one bundle plugin per preset in scripts/presets.json (dependencies on the books and on `guided`)
// The hand-written parts of meta/guided (manifest, skills, README) are not touched.
//   node scripts/gen-guided.mjs            write
//   node scripts/gen-guided.mjs --check    fail when a generated file is stale (CI)
import fs from 'node:fs';
import path from 'node:path';
import { REGISTRY, ROOT } from './lib.mjs';
import { pairTable } from './guided-config-lib.mjs';

const check = process.argv.includes('--check');
const META = path.join(ROOT, 'meta');
const read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8');
const readIf = (p) => (fs.existsSync(path.join(ROOT, p)) ? read(p) : null);
const presets = JSON.parse(read('scripts/presets.json')).presets;
const core = JSON.parse(readIf('scripts/core.json') ?? '{}');
const stale = [];

function write(rel, text) {
  const file = path.join(ROOT, rel);
  const body = text.endsWith('\n') ? text : `${text}\n`;
  const have = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
  if (have === body) return;
  if (check) { stale.push(rel); return; }
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, body);
}
const titleOf = (slug) => REGISTRY.books.find((b) => b.slug === slug).title;
const GENERATED = '<!-- Generated by scripts/gen-guided.mjs from the repository. Do not edit by hand. -->';

// ---------------------------------------------------------------- books.md
const STANDARD = ['review', 'plan', 'checklist', 'fix'];
const books = [
  GENERATED, '', '# The 14 books', '',
  'Each book is a plugin. Install one with `/plugin install <slug>@guided-plugins`. `review` always exists; so do `audit`, `plan`, `checklist`, `fix` and `explain-rule`.', '',
  '| Slug | Book | Author | Reach for it when | Core workflows and agents |', '| --- | --- | --- | --- | --- |',
  ...REGISTRY.books.map((b) => {
    const c = core[b.slug];
    const flows = (c?.workflows ?? STANDARD).map((w) => `\`/${b.slug}:${w}\``);
    const extra = c ? [...(c.skills ?? []).map((s) => `\`/${b.slug}:${s}\``), ...(c.agents ?? []).map((a) => `\`${b.slug}:${a}\``)] : [];
    return `| \`${b.slug}\` | ${b.title} | ${b.bookAuthor} | ${b.usefulWhen} | ${[...flows, ...extra].join(', ')} |`;
  }),
  '', '## Presets', '',
  'A preset is one primary book and up to two secondary books that are rated Complementary with it and with each other. Claude Code installs a preset with `/plugin install guided-<preset>@guided-plugins` (the books and the `guided` plugin).', '',
  '| Preset | For | Primary | Secondary | Why |', '| --- | --- | --- | --- | --- |',
  ...presets.map((p) => `| \`${p.name}\` | ${p.forWho} | \`${p.primary}\` | ${p.secondary.map((s) => `\`${s}\``).join(', ')} | ${p.why} |`),
  '',
];
write('meta/guided/skills/which-book/references/books.md', books.join('\n'));

// ---------------------------------------------------------------- pairs.md
const seen = new Set(); const rows = [];
for (const row of pairTable().values()) {
  const key = [row.a, row.b].sort().join('|');
  if (seen.has(key)) continue;
  seen.add(key); rows.push(row);
}
rows.sort((x, y) => x.a.localeCompare(y.a) || x.b.localeCompare(y.b));
write('meta/guided/skills/conflicts/references/pairs.md', [
  GENERATED, '', '# How each pair of books relates', '',
  'From the compatibility guide (91 pairs). **Complementary**: install both, use the second where its trigger is present. **Overlap**: choose one as primary; use the other only for a narrow, named decision. **Conflicting**: do not use as equals; the two can push opposite decisions on the same code.',
  'Percentages: conflict (how often their rules oppose), overlap (how much they say the same), complementarity (how much one adds to the other).', '',
  '| Book A | Book B | Verdict | Conflict | Overlap | Complementarity |', '| --- | --- | --- | ---: | ---: | ---: |',
  ...rows.map((r) => `| \`${r.a}\` | \`${r.b}\` | ${r.verdict} | ${r.conflict}% | ${r.overlap}% | ${r.complementarity}% |`), '',
].join('\n'));

// ---------------------------------------------------------------- copies of repository documents
const copies = [
  ['docs/COMPATIBILITY.md', 'meta/guided/skills/conflicts/references/compatibility.md'],
  ['docs/guided-plugins.schema.json', 'meta/guided/skills/config/references/guided-plugins.schema.json'],
  ['docs/PROJECT_CONFIG.md', 'meta/guided/skills/config/references/PROJECT_CONFIG.md'],
  ['docs/findings.schema.json', 'meta/guided/skills/review/references/findings.schema.json'],
  ['docs/CI.md', 'meta/guided/skills/ci-setup/references/CI.md'],
  ['docs/examples/guided-review.yml', 'meta/guided/skills/ci-setup/references/guided-review.yml'],
  ['LICENSE', 'meta/guided/LICENSE'],
];
for (const [from, to] of copies) {
  let text = read(from);
  if (from.endsWith('.md')) text = `${GENERATED}\n\n${text}`;
  write(to, text);
}

// ---------------------------------------------------------------- bundles
for (const p of presets) {
  const name = `guided-${p.name}`;
  const dir = `meta/bundles/${name}`;
  const members = [p.primary, ...p.secondary];
  write(`${dir}/.claude-plugin/plugin.json`, JSON.stringify({
    name,
    displayName: `Guided Plugins preset: ${p.title}`,
    version: '1.0.0',
    description: `${p.title}: installs ${members.map(titleOf).join(', ')} and the guided companion in one step. ${p.forWho}`,
    author: { name: REGISTRY.marketplace.owner },
    homepage: `https://github.com/${REGISTRY.marketplace.githubRepo}/tree/main/${dir}`,
    repository: `https://github.com/${REGISTRY.marketplace.githubRepo}`,
    license: 'MIT',
    keywords: ['preset', 'bundle', ...members],
    dependencies: [...members, 'guided'],
  }, null, 2));
  write(`${dir}/README.md`, `${[
    `# ${p.title} (Guided Plugins preset)`, '',
    `${p.forWho} This bundle contains no skills of its own. Installing it installs the plugins below as dependencies:`, '',
    `| Role | Plugin | Book |`, `| --- | --- | --- |`,
    `| Primary | \`${p.primary}\` | ${titleOf(p.primary)} |`,
    ...p.secondary.map((s) => `| Secondary | \`${s}\` | ${titleOf(s)} |`),
    `| Companion | \`guided\` | start, which-book, config, review (across books), conflicts, ci-setup |`, '',
    `**Why these.** ${p.why} Every pair is rated Complementary in the compatibility guide, so the books can run side by side; the primary book decides if they ever disagree.`, '',
    '## Use it', '',
    '```text',
    `/plugin marketplace add ${REGISTRY.marketplace.githubRepo}`,
    `/plugin install ${name}@${REGISTRY.marketplace.name}`,
    `/guided:config ${p.name}            # writes .guided-plugins.json with this primary and secondary`,
    `/${p.primary}:review                 # a review of your current diff`,
    `/guided:review                       # one review across all ${members.length} books`,
    '```', '',
    `Uninstalling the bundle leaves the plugins installed; remove them one by one with \`/plugin uninstall\`. More: [the repository](https://github.com/${REGISTRY.marketplace.githubRepo}).`, '',
    'MIT licensed, unofficial, not endorsed by the authors or publishers of the books. See the repository NOTICE.', '',
  ].join('\n')}`);
  write(`${dir}/LICENSE`, read('LICENSE'));
}

// ---------------------------------------------------------------- the presets table in README.md
{
  const rel = 'README.md';
  const text = read(rel);
  const START = '<!-- PRESETS:START -->'; const END = '<!-- PRESETS:END -->';
  if (text.includes(START) && text.includes(END)) {
    const table = [
      '| Preset | For | Primary | Secondary | Install (Claude Code) |', '| --- | --- | --- | --- | --- |',
      ...presets.map((p) => `| \`${p.name}\` | ${p.forWho} | \`${p.primary}\` | ${p.secondary.map((x) => `\`${x}\``).join(', ')} | \`/plugin install guided-${p.name}@${REGISTRY.marketplace.name}\` |`),
    ].join('\n');
    write(rel, `${text.slice(0, text.indexOf(START) + START.length)}\n\n${table}\n\n${text.slice(text.indexOf(END))}`);
  }
}

if (check) {
  if (stale.length) { console.error(`stale generated files (run: node scripts/gen-guided.mjs):\n  ${stale.join('\n  ')}`); process.exit(1); }
  console.log('meta/ is up to date');
} else console.log(`meta/ written (${presets.length} bundles, ${copies.length} copies, ${rows.length} pairs)`);
